import {
  ATTACHMENT_LINK,
  HYPERLINK_LINK,
  PARENT_LINK_FORWARD,
  PARENT_LINK_REVERSE,
  PREDECESSOR_LINK,
  RELATED_LINK,
  SUCCESSOR_LINK
} from "./constants";
import { parentIdFromRelations, stripHtml, workItemIdFromRelationUrl, workItemWebUrl } from "./fields";
import {
  WorkItemCommentInfo,
  WorkItemDetails,
  WorkItemLike,
  WorkItemLinkInfo,
  WorkItemRelation
} from "./types";

const LINK_LABELS: Record<string, string> = {
  [RELATED_LINK]: "Related",
  [PREDECESSOR_LINK]: "Predecessor",
  [SUCCESSOR_LINK]: "Successor",
  [PARENT_LINK_REVERSE]: "Parent",
  [PARENT_LINK_FORWARD]: "Child",
  [HYPERLINK_LINK]: "Hyperlink"
};

export const ADDABLE_LINK_TYPES: Array<{ rel: string; label: string }> = [
  { rel: RELATED_LINK, label: "Related" },
  { rel: PREDECESSOR_LINK, label: "Predecessor" },
  { rel: SUCCESSOR_LINK, label: "Successor" }
];

export function relationLabel(rel: string): string {
  return LINK_LABELS[rel] || rel.replace(/^.*\./, "");
}

export function workItemLinksFromRelations(
  relations: WorkItemRelation[] | undefined,
  orgUrl: string,
  project: string
): { links: WorkItemLinkInfo[]; attachments: WorkItemLinkInfo[] } {
  const links: WorkItemLinkInfo[] = [];
  const attachments: WorkItemLinkInfo[] = [];
  (relations || []).forEach((relation, index) => {
    const rel = String(relation.rel || "");
    const url = String(relation.url || "");
    if (!rel || !url) {
      return;
    }
    const name =
      typeof relation.attributes?.name === "string" ? relation.attributes.name : undefined;
    const id = workItemIdFromRelationUrl(url);
    const info: WorkItemLinkInfo = {
      index,
      rel,
      label: relationLabel(rel),
      url: id ? workItemWebUrl(orgUrl, project, id) : url,
      id,
      name
    };
    if (rel === ATTACHMENT_LINK) {
      attachments.push({ ...info, label: name || "Attachment" });
      return;
    }
    if (rel === PARENT_LINK_FORWARD || rel === PARENT_LINK_REVERSE) {
      return;
    }
    links.push(info);
  });
  return { links, attachments };
}

export function mapWorkItemComments(
  raw: Array<{ id?: number; text?: string; createdBy?: { displayName?: string }; createdDate?: string }>
): WorkItemCommentInfo[] {
  return raw
    .map((comment) => ({
      id: Number(comment.id) || 0,
      text: stripHtml(String(comment.text || "")).trim(),
      createdBy: String(comment.createdBy?.displayName || "").trim() || "Unknown",
      createdDate: String(comment.createdDate || "")
    }))
    .filter((comment) => comment.id && comment.text);
}

export function workItemDetailsFromSources(
  item: WorkItemLike,
  orgUrl: string,
  project: string,
  comments: WorkItemCommentInfo[],
  parent?: { id: number; title: string }
): WorkItemDetails {
  const id = item.id || 0;
  const { links, attachments } = workItemLinksFromRelations(item.relations, orgUrl, project);
  const parentId = parent?.id || parentIdFromRelations(item);
  return {
    id,
    rev: typeof item.rev === "number" ? item.rev : undefined,
    title: String(item.fields?.["System.Title"] || "").trim(),
    webUrl: workItemWebUrl(orgUrl, project, id),
    parentId: parentId || undefined,
    parentTitle: parent?.title || "",
    parentUrl: parentId ? workItemWebUrl(orgUrl, project, parentId) : undefined,
    links,
    attachments,
    comments
  };
}

export function commentHtml(text: string): string {
  const escaped = text
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
  return `<div>${escaped.replace(/\n/g, "<br/>")}</div>`;
}
